from pathlib import Path
import pandas as pd,numpy as np,json
from scipy.stats import norm
O=Path('outputs');W=Path('work');b=pd.read_csv(O/'stage6_rbm6_gtex_direct_aligned.csv');names=['chromosome','pos','ea','oa','odds_ratio','se','eaf','p','rsid','ci_upper','ci_lower','alt','n','case_af','num_cases','control_af','num_controls','r2','q_pval','i2','direction','hm_code','hm_chr','hm_variant'];m=pd.read_csv(W/'stage6_rbm6_mvp_harmonised_region.tsv',sep='\t',names=names);m=m[m.chromosome.eq(3)&m.ea.isin(list('ACGT'))&m.oa.isin(list('ACGT'))].copy();m['pair']=m.apply(lambda r:''.join(sorted([r.ea,r.oa])),axis=1);m=m[m.pair.isin(['AC','AG','CT','GT'])].copy();m=m.drop_duplicates(['pos','pair'],keep=False);m=m[(m.odds_ratio>0)&(m.odds_ratio!=1)&m.p.between(0,1,inclusive='neither')&m.eaf.between(0,1)].copy();m=m.rename(columns={c:'mvp_'+c for c in m.columns if c not in ['pos','pair']});x=b.reset_index(names='ld_row').merge(m,left_on=['position','pair'],right_on=['pos','pair'],validate='one_to_one');x['mvp_z']=np.where(x.mvp_ea==x.anchor_effect_allele,1,-1)*np.sign(np.log(x.mvp_odds_ratio))*norm.isf(x.mvp_p/2);x['mvp_af_anchor']=np.where(x.mvp_ea==x.anchor_effect_allele,x.mvp_eaf,1-x.mvp_eaf);x['mvp_af_diff']=abs(x.mvp_af_anchor-x.nfe_anchor_af);before=len(x);x=x[x.mvp_af_diff.le(.2)&np.isfinite(x.mvp_z)].copy();x.to_csv(O/'stage6_rbm6_gtex_mvp_aligned.csv',index=False);pub=pd.read_csv(O/'stage6_rbm6_gtex_cortex_published_cs_coverage.tsv',sep='\t').drop_duplicates(['cs_id','variant']);match=pub[pub.variant.isin(set(x.variant))];receipt={'base_frailty_qtl_reference_count':len(b),'matched_before_af':before,'retained':len(x),'mean_af_diff':float(x.mvp_af_diff.mean()),'max_af_diff':float(x.mvp_af_diff.max()),'top_present':bool(x.variant.eq('chr3_50085532_T_C').any()),'published_cs_matched':len(match),'published_cs_pip_sum_matched':float(match.pip.sum()),'published_cs_pip_sum_total':float(pub.pip.sum()),'mvp_note':'Z derived from signed rounded OR and p; source has no standard errors. Position/allele match and external frequency QC.'};(O/'stage6_rbm6_gtex_mvp_align_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2))
